svg.script:
// SoakHub settings: paste your deployed Cloudflare Worker URL here.
// Do NOT put your Gemini API key in this SVG.
const CHAT_ENDPOINT = 'https://YOUR-WORKER.YOUR-SUBDOMAIN.workers.dev/';
const ASSETS = 'https://cdn.jsdelivr.net/gh/n1honium/SoakHub-Assets/';
const games = [
  {name:'Among Us',file:'AmongUs.html',image:'AmongUs.png',genre:'Social'},
  {name:'A Dance of Fire and Ice',file:'A-Dance-Of-Fire-And-Ice.html',image:'A-Dance-Of-Fire-And-Ice.png',genre:'Rhythm'},
  {name:'Brotato',file:'Brotato.html',image:'Brotato.jpeg',genre:'Action'},
  {name:'Binding of Isaac',file:'Binding-of-Isaac.html',image:'Binding-of-Isaac.png',genre:'Roguelike'},
  {name:'Bitlife',file:'Bitlife.html',image:'Bitlife.png',genre:'Simulation'},
  {name:'Basketball Stars',file:'Basketball-Stars.html',image:'Basketball-Stars.jpeg',genre:'Sports'}
];
const $ = id => document.getElementById(id);
const grid = $('games');
const gameFrame = $('game-frame');
let favorites = new Set();
try {favorites = new Set(JSON.parse(localStorage.getItem('soakhub-favorites')||'[]'));} catch(e) {}
let requestId=0;
const history=[];
const SVGNS='http://www.w3.org/2000/svg';
const NS='http://www.w3.org/1999/xhtml';

function el(tag,className,text){ const node=document.createElementNS(NS,tag);if(className)node.className=className;if(text!==undefined)node.textContent=text;return node; }
function iconPath(d){const s=document.createElementNS(SVGNS,'svg');s.setAttribute('viewBox','0 0 24 24');s.setAttribute('width','21');s.setAttribute('height','21');s.setAttribute('fill','none');s.setAttribute('stroke','currentColor');s.setAttribute('stroke-width','2');s.setAttribute('stroke-linecap','round');s.setAttribute('stroke-linejoin','round');const path=document.createElementNS(SVGNS,'path');path.setAttribute('d',d);s.appendChild(path);return s;}
function filteredGames(){ const q=$('search').value.toLowerCase().trim(); const type=$('genre').value;const sort=$('sort').value;const filtered=games.filter(g=>g.name.toLowerCase().includes(q)&&(type==='all'||g.genre===type||(type==='favorites'&&favorites.has(g.name))));if(sort==='az')filtered.sort((a,b)=>a.name.localeCompare(b.name));if(sort==='za')filtered.sort((a,b)=>b.name.localeCompare(a.name));return filtered; }
function render(){
  grid.replaceChildren();const visible=filteredGames();$('total-count').textContent=String(games.length).padStart(2,'0');$('visible-count').textContent=visible.length;$('empty').style.display=visible.length?'none':'block';
  visible.forEach(game=>{
    const card=el('article','game-card');card.setAttribute('tabindex','0');card.setAttribute('role','button');card.setAttribute('aria-label','Play '+game.name);
    const art=el('div','game-art');const image=el('img');image.src=ASSETS+game.image;image.alt=game.name+' cover';image.loading='lazy';
    image.onerror=()=>{image.onerror=null;image.style.display='none';art.style.background='linear-gradient(135deg,#1b4778,#0a192b)';};
    art.appendChild(image);art.appendChild(el('div','art-overlay'));
    const play=el('div','play-circle');play.appendChild(iconPath('m9 6 10 6-10 6z'));art.appendChild(play);
    const fav=el('button','favorite'+(favorites.has(game.name)?' is-fav':''));fav.setAttribute('aria-label',(favorites.has(game.name)?'Unfavorite ':'Favorite ')+game.name);fav.title='Toggle favorite';fav.appendChild(iconPath('m12 3 2.7 5.7 6.3.9-4.5 4.4 1.1 6.3-5.6-3-5.6 3 1.1-6.3-4.5-4.4 6.3-.9z'));
    fav.addEventListener('click',e=>{e.stopPropagation();if(favorites.has(game.name))favorites.delete(game.name);else favorites.add(game.name);try{localStorage.setItem('soakhub-favorites',JSON.stringify([...favorites]));}catch(err){}render();});
    art.appendChild(fav);card.appendChild(art);
    const footer=el('div','card-footer');footer.appendChild(el('div','game-title',game.name));footer.appendChild(el('div','game-genre',game.genre));card.appendChild(footer);
    card.addEventListener('click',()=>openGame(game));card.addEventListener('keydown',e=>{if(e.target===card&&(e.key==='Enter'||e.key===' ')){e.preventDefault();openGame(game);}});
    grid.appendChild(card);
  });
}
function showLoad(title,description,failed=false){$('load-title').textContent=title;$('load-hint').textContent=description;$('loadscreen').className='loadscreen'+(failed?' failed':'');$('loading-bar').style.display=failed?'none':'block';}
async function openGame(game){
  const token=++requestId;
  $('player-name').textContent=game.name;
  $('player').classList.add('active');$('player').setAttribute('aria-hidden','false');
  $('chat-panel').classList.remove('open');
  gameFrame.removeAttribute('srcdoc');showLoad('Loading '+game.name,'Downloading the game file...');
  try{
    const url=ASSETS+game.file;
    const response=await fetch(url,{cache:'default'});
    if(!response.ok)throw new Error('HTTP '+response.status+' while fetching the game');
    let html=await response.text();
    if(token!==requestId)return;
    const base='<base href="'+url+'" />';
    if(/<head\b[^>]*>/i.test(html))html=html.replace(/<head\b[^>]*>/i,match=>match+base);
    else html=base+html;
    showLoad('Starting '+game.name,'The game may display its own loading screen.');
    gameFrame.onload=()=>{if(token===requestId){$('loadscreen').classList.add('done');}};
    gameFrame.srcdoc=html;
  }catch(err){
    if(token!==requestId)return;
    console.error('SoakHub game failed:',err);
    showLoad('Could not load '+game.name,'The game file may be unavailable or blocked by the browser. '+err.message,true);
  }
}
function closeGame(){requestId++;gameFrame.onload=null;gameFrame.removeAttribute('srcdoc');gameFrame.src='about:blank';$('player').classList.remove('active');$('player').setAttribute('aria-hidden','true');}
$('close-game').addEventListener('click',closeGame);
$('fullscreen').addEventListener('click',()=>{const host=$('player');if(!document.fullscreenElement){const promise=host.requestFullscreen?host.requestFullscreen():null;if(promise&&promise.catch)promise.catch(err=>console.warn('Fullscreen unavailable:',err));}else if(document.exitFullscreen)document.exitFullscreen();});
$('search').addEventListener('input',render);$('genre').addEventListener('change',render);$('sort').addEventListener('change',render);
$('random-game').addEventListener('click',()=>{const visible=filteredGames();const pool=visible.length?visible:games;openGame(pool[Math.floor(Math.random()*pool.length)]);});
$('chat-toggle').addEventListener('click',()=>{$('chat-panel').classList.toggle('open');if($('chat-panel').classList.contains('open'))$('chat-input').focus();});
$('chat-close').addEventListener('click',()=>{$('chat-panel').classList.remove('open');});
function bubble(text,asUser=false){const msg=el('div','bubble'+(asUser?' user':''),text);$('messages').appendChild(msg);$('messages').scrollTop=$('messages').scrollHeight;return msg;}
$('chat-form').addEventListener('submit',async e=>{
  e.preventDefault();const input=$('chat-input');const question=input.value.trim();if(!question||$('send-chat').disabled)return;
  input.value='';bubble(question,true);
  if(CHAT_ENDPOINT.includes('YOUR-WORKER')){bubble('AI setup needed: deploy the included Cloudflare Worker, then set CHAT_ENDPOINT in SoakHub.svg to its URL. Do not embed the API key in the SVG.');return;}
  const reply=bubble('Thinking...');$('send-chat').disabled=true;
  try{
    const res=await fetch(CHAT_ENDPOINT,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({message:question,history:history.slice(-8)})});
    const data=await res.json();if(!res.ok)throw new Error(data.error||'Server error '+res.status);
    if(!data.reply)throw new Error('Empty response');reply.textContent=data.reply;
    history.push({role:'user',text:question},{role:'model',text:data.reply});if(history.length>8)history.splice(0,history.length-8);
  }catch(err){reply.textContent='AI unavailable: '+err.message;}finally{$('send-chat').disabled=false;input.focus();$('messages').scrollTop=$('messages').scrollHeight;}
});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('chat-panel').classList.contains('open'))$('chat-panel').classList.remove('open');else if($('player').classList.contains('active')&&!document.fullscreenElement)closeGame();}});
render();
